    danmu: { icon: 'comment', label: '\u5F39\u5E55\u914D\u7F6E', description: '\u8FC7\u6EE4\u3001\u8F6C\u6362\u3001\u8F93\u51FA\u4E0E\u65F6\u95F4\u8C03\u6574' },
